37		if !ok {
38			return Delivery{Message: message.ID, Status: "rejected", Reason: "unknown source chain"}
39		}
40		if !header.Trusted || header.Height < message.ProofAt {
41			return Delivery{Message: message.ID, Status: "pending", Reason: "header not yet trusted at proof height"}
42		}
43		key := message.From + ":" + message.To + ":" + strconv.FormatUint(message.Nonce, 10)
44		if consumed[key] {
45			return Delivery{Message: message.ID, Status: "rejected", Reason: "replay: nonce already consumed"}
46		}
47		consumed[key] = true
48		return Delivery{Message: message.ID, Status: "delivered", Reason: "proof verified at height " + strconv.FormatInt(header.Height, 10)}
49	}
