// repeatReader hands out chunks of a repeated byte pattern and reports fault
// after faultAfter bytes have been delivered, so bufio pulls data through
// multiple Read calls before the interruption.
type repeatReader struct {
	chunks      []string
	pos         int
	fault       error
	faultAfter  int
	delivered   int
	faulted     bool
}

func (r *repeatReader) Read(p []byte) (int, error) {
	if r.faulted {
		return 0, r.fault
	}
	if r.pos >= len(r.chunks) {
		r.faulted = true
		return 0, r.fault
	}
	n := copy(p, r.chunks[r.pos])
	r.pos++
	r.delivered += n
	if r.faultAfter >= 0 && r.delivered >= r.faultAfter {
		r.faulted = true
		return n, r.fault
	}
	return n, nil
}

