// failingWriter records every byte it accepts until failAfter writes; the
// next Write fails with writeFault and every Write afterwards fails too. A
// negative failAfter keeps the writer healthy (used as a plain sink).
type failingWriter struct {
	varb      bytes.Buffer
	failAfter int // number of successful Write calls before failing
	write     int
	fault     error
}

func (w *failingWriter) Write(p []byte) (int, error) {
	if w.failAfter >= 0 && w.write >= w.failAfter {
		return 0, w.fault
	}
	w.write++
	return w.varb.Write(p)
}

