13	// These regressions pin down how NormalizeReader reports input/output
14	// interruptions separately from per-line validation failures:
15	//
16	//   - a line that fails normalization is data, not an I/O fault: it stays in
17	//     the output with its physical line number, later lines keep processing,
18	//     and the returned error is nil;
19	//   - a read fault after complete lines surfaces as the returned error,
20	//     already read lines are still emitted in order, and the fault is never
21	//     counted as a failed log or rendered as an extra event/line error;
22	//   - a write fault (mid-stream or while flushing the final batch) surfaces
23	//     as the returned error without changing the accumulated failure count;
24	//   - when both a read fault and a close-time write fault happen, the earlier
25	//     read fault is what the caller receives;
26	//   - clean EOF, including a final line without a newline, stays error-free.
27	//
28	// All faults are produced by in-memory test doubles, so the behavior is
29	// reproduced offline and deterministically with no network or device reliance.
30	
31	var (
32		errBoomRead  = errors.New("synthetic read interruption")
33		errBoomWrite = errors.New("synthetic write interruption")
34	)
35	
36	// failingReader serves prefix verbatim, then returns (readFault, nil) on the
37	// next Read and forever after.
38	type failingReader struct {
39		prefix    string
40		readFault error
41		read      bool
42	}
43	
44	func (f *failingReader) Read(p []byte) (int, error) {
45		if f.read {
46			return 0, f.readFault
47		}
48		f.read = true
49		return copy(p, f.prefix), nil
50	}
51	
52	// repeatReader hands out one chunk per Read call. When faultWithLast is true
53	// the final chunk is delivered together with fault (bufio keeps those bytes
54	// while remembering the pending error); otherwise fault is reported on the
55	// Read after the chunks run out.
56	type repeatReader struct {
57		chunks        []string
58		pos           int
59		fault         error
60		faultWithLast bool
61		faulted       bool
62	}
63	
64	func (r *repeatReader) Read(p []byte) (int, error) {
65		if r.faulted {
66			return 0, r.fault
67		}
68		if r.pos >= len(r.chunks) {
69			r.faulted = true
70			return 0, r.fault
71		}
72		n := copy(p, r.chunks[r.pos])
73		r.pos++
74		if r.faultWithLast && r.pos >= len(r.chunks) {
75			r.faulted = true
76			return n, r.fault
77		}
78		return n, nil
79	}
80	
81	// failingWriter records every byte it accepts until failAfter writes; the
82	// next Write fails with fault and every Write afterwards fails too.
83	type failingWriter struct {
84		sink      bytes.Buffer
85		failAfter int // number of successful Write calls before failing
86		write     int
87		fault     error
88	}
89	
90	func (w *failingWriter) Write(p []byte) (int, error) {
91		if w.write >= w.failAfter {
92			return 0, w.fault
93		}
94		w.write++
95		return w.sink.Write(p)
96	}
97	
98	// decodeResultsLenient parses as many complete JSON result objects as the
99	// output contains. After a write interruption the residue may be a partial
100	// JSON line, so a trailing decode error is expected and ignored here; tests
101	// that need a guaranteed-complete output decode the prefix explicitly.
102	func decodeResultsLenient(t *testing.T, raw []byte) []map[string]any {
103		t.Helper()
104		var results []map[string]any
105		dec := json.NewDecoder(bytes.NewReader(raw))
106		for {
107			var m map[string]any
108			if err := dec.Decode(&m); err != nil {
109				break
110			}
111			results = append(results, m)
112		}
113		return results
114	}
115	
116	// assertResultsComplete decodes exactly want results and fails if the output
117	// is truncated or contains anything after the last object.
118	func assertResultsComplete(t *testing.T, raw []byte, want int) []map[string]any {
119		t.Helper()
120		var results []map[string]any
121		dec := json.NewDecoder(bytes.NewReader(raw))
122		for {
123			var m map[string]any
124			if err := dec.Decode(&m); err != nil {
125				if !errors.Is(err, io.EOF) {
126					t.Fatalf("output must be %d complete JSON lines, decode failed: %v; output=%q", want, err, raw)
127				}
128				break
129			}
130			results = append(results, m)
131		}
132		if len(results) != want {
133			t.Fatalf("expected %d complete result lines, got %d: %q", want, len(results), raw)
134		}
135		return results
136	}
137	
138	func validLog(action string) string {
139		return `{"timestamp":"2026-01-02T00:00:00Z","action":"` + action + `"}`
140	}
141	
142	// TestNormalizeInvalidLineIsDataNotIOError reproduces the baseline contract:
143	// an invalid log line amid legal ones is a numbered per-line failure, later
144	// legal logs still come out, and — with healthy I/O — the run error is nil
145	// while the failure count reflects only the bad logs themselves.
146	func TestNormalizeInvalidLineIsDataNotIOError(t *testing.T) {
147		input := validLog("a") + "\n" +
148			"not json at all\n" +
149			`{"timestamp":"bad","action":"c"}` + "\n" +
150			validLog("d") + "\n"
151		var out bytes.Buffer
152		failures, err := NormalizeReader(strings.NewReader(input), &out)
153		if err != nil {
154			t.Fatalf("per-line validation failures must not surface as an I/O error, got %v", err)
155		}
156		if failures != 2 {
157			t.Fatalf("failures must count exactly the two invalid logs, got %d", failures)
158		}
159		results := assertResultsComplete(t, out.Bytes(), 4)
160		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
161			t.Fatalf("line 1: %#v", results[0])
162		}
163		if results[1]["line"] != float64(2) || results[1]["ok"] != false {
164			t.Fatalf("invalid line must keep its original line number: %#v", results[1])
165		}
166		if results[2]["line"] != float64(3) || results[2]["ok"] != false {
167			t.Fatalf("invalid line must keep its original line number: %#v", results[2])
168		}
169		if results[3]["line"] != float64(4) || results[3]["ok"] != true {
170			t.Fatalf("later legal line must still be output: %#v", results[3])
171		}
172		if eventOf(t, results[3])["action"] != "d" || eventOf(t, results[0])["action"] != "a" {
173			t.Fatalf("output order must match input order: %#v", results)
174		}
175		if msg, _ := results[2]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
176			t.Fatalf("line error must stay recognizable as a field error, got %q", msg)
177		}
178	}
179	
180	// TestNormalizeReadErrorAfterCompleteLines: when the input stream breaks
181	// after several complete log lines, everything already read is processed in
182	// order and flushed out (both success events and per-line error records), the
183	// returned error is the read fault, and it is not counted as a log failure.
184	func TestNormalizeReadErrorAfterCompleteLines(t *testing.T) {
185		// Delivered in separate chunks so bufio cannot see the fault as part of
186		// any later Read: three complete lines, the middle one invalid.
187		r := &repeatReader{
188			chunks: []string{
189				validLog("a") + "\n",
190				"not json\n",
191				validLog("c") + "\n",
192			},
193			fault:      errBoomRead,
194			faultAfter: -1,
195		}
196		var out bytes.Buffer
197		failures, err := NormalizeReader(r, &out)
198		if !errors.Is(err, errBoomRead) {
199			t.Fatalf("caller must receive the read error, got %v", err)
200		}
201		if failures != 1 {
202			t.Fatalf("read fault must not be counted as a failed log; expected 1 (the invalid line), got %d", failures)
203		}
204		results := assertResultsComplete(t, out.Bytes(), 3)
205		if results[0]["line"] != float64(1) || results[0]["ok"] != true || eventOf(t, results[0])["action"] != "a" {
206			t.Fatalf("line 1 success must be written: %#v", results[0])
207		}
208		if results[1]["line"] != float64(2) || results[1]["ok"] != false {
209			t.Fatalf("line 2 per-line error must be written with its line number: %#v", results[1])
210		}
211		if results[2]["line"] != float64(3) || results[2]["ok"] != true || eventOf(t, results[2])["action"] != "c" {
212			t.Fatalf("line 3 success must be written: %#v", results[2])
213		}
214	}
215	
216	// TestNormalizeReadErrorOnTrailingFragment: bytes past the last newline that
217	// arrive together with a non-EOF read fault are an unresolved fragment, not a
218	// final log. The fault must produce no event and no fabricated line-level
219	// failure, must not advance the line counter, and the complete lines already
220	// read are still emitted.
221	func TestNormalizeReadErrorOnTrailingFragment(t *testing.T) {
222		for _, fragment := range []string{
223			`{"timestamp":"2026-01-02T00:00:00Z","action":`, // would-be legal, cut off
224			`{"timestamp":"2026-01-02T00:00:00Z","action":"x"}`, // complete-looking object, but no newline
225			"not json either", // outright garbage
226		} {
227			t.Run(fmt.Sprintf("fragment=%q", fragment), func(t *testing.T) {
228				r := &repeatReader{
229					chunks: []string{
230						validLog("a") + "\n",
231						fragment,
232					},
233					fault:      errBoomRead,
234					faultAfter: -1,
235				}
236				var out bytes.Buffer
237				failures, err := NormalizeReader(r, &out)
238				if !errors.Is(err, errBoomRead) {
239					t.Fatalf("caller must receive the read error, got %v", err)
240				}
241				if failures != 0 {
242					t.Fatalf("fault fragment must not create a per-line failure, got failures=%d", failures)
243				}
244				results := assertResultsComplete(t, out.Bytes(), 1)
245				if results[0]["line"] != float64(1) || results[0]["ok"] != true {
246					t.Fatalf("only the completed line 1 must be emitted, got %#v", results)
247				}
248			})
249		}
250	}
251	
252	// TestNormalizeReadErrorAfterInvalidLinesCountPreserved: with multiple invalid
253	// lines already accumulated, a read fault leaves the failure count exactly at
254	// the number of invalid logs and is still returned as the error.
255	func TestNormalizeReadErrorAfterInvalidLinesCountPreserved(t *testing.T) {
256		r := &failingReader{
257			prefix: "garbage1\n" + "garbage2\n" + validLog("ok") + "\n",
258		}
259		r.readFault = errBoomRead
260		var out bytes.Buffer
261		failures, err := NormalizeReader(r, &out)
262		if !errors.Is(err, errBoomRead) {
263			t.Fatalf("caller must receive the read error, got %v", err)
264		}
265		if failures != 2 {
266			t.Fatalf("failures must stay at the 2 invalid logs, fault adds none, got %d", failures)
267		}
268		results := assertResultsComplete(t, out.Bytes(), 3)
269		if results[0]["ok"] != false || results[0]["line"] != float64(1) ||
270			results[1]["ok"] != false || results[1]["line"] != float64(2) ||
271			results[2]["ok"] != true || results[2]["line"] != float64(3) {
272			t.Fatalf("all three complete lines must be emitted in order: %#v", results)
273		}
274	}
275	
276	// TestNormalizeWriteFailureMidStream forces the underlying writer to fail on
277	// an early Write call (the buffered writer must flush to reach it). The write
278	// fault is returned, the residue may be partial JSON, and no ordinary log
279	// failure record is synthesized for it.
280	func TestNormalizeWriteFailureMidStream(t *testing.T) {
281		// Each line is ~60 bytes and 20 lines far exceed bufio's 4 KiB buffer,
282		// guaranteeing a real underlying Write happens mid-stream; failAfter=1
283		// makes that first flush fail.
284		var sb strings.Builder
285		for i := 0; i < 20; i++ {
286			sb.WriteString(validLog(fmt.Sprintf("action-%02d", i)))
287			sb.WriteByte('\n')
288		}
289		w := &failingWriter{failAfter: 0, fault: errBoomWrite}
290		failures, err := NormalizeReader(strings.NewReader(sb.String()), w)
291		if !errors.Is(err, errBoomWrite) {
292			t.Fatalf("caller must receive the write error, got %v", err)
293		}
294		if failures != 0 {
295			t.Fatalf("write fault must not add failures when all logs are legal, got %d", failures)
296		}
297		if w.varb.Len() != 0 {
298			t.Fatalf("failing writer must leave no residue on the failed Write, got %q", w.varb.Bytes())
299		}
300	}
301	
302	// TestNormalizeWriteFailureKeepsAccumulatedFailures: when invalid logs have
303	// already accumulated and the output then breaks, the write fault is returned
304	// and the failure count is neither bumped (fault is not a bad log) nor reset.
305	func TestNormalizeWriteFailureKeepsAccumulatedFailures(t *testing.T) {
306		var sb strings.Builder
307		sb.WriteString("bad line one\n") // invalid -> failure
308		for i := 0; i < 40; i++ {
309			sb.WriteString(validLog(fmt.Sprintf("action-%02d", i)))
310			sb.WriteByte('\n')
311		}
312		sb.WriteString("bad line two\n") // invalid -> failure
313		for i := 0; i < 40; i++ {
314			sb.WriteString(validLog(fmt.Sprintf("more-%02d", i)))
315			sb.WriteByte('\n')
316		}
317		w := &failingWriter{failAfter: 1, fault: errBoomWrite}
318		failures, err := NormalizeReader(strings.NewReader(sb.String()), w)
319		if !errors.Is(err, errBoomWrite) {
320			t.Fatalf("caller must receive the write error, got %v", err)
321		}
322		if failures != 2 {
323			t.Fatalf("accumulated per-line failures must survive (expected 2), write fault adds none, got %d", failures)
324		}
325	}
326	
327	// TestNormalizeWriteFailureAtFinalFlush: healthy input of all-legal logs that
328	// only fails when the last buffered batch is written at the end must still
329	// hand the caller the write error; a write fault cannot turn into success.
330	func TestNormalizeWriteFailureAtFinalFlush(t *testing.T) {
331		// Small input that fits inside the 4 KiB buffer, so nothing is written
332		// until the deferred flush at input EOF.
333		input := validLog("only") + "\n"
334		w := &failingWriter{failAfter: 0, fault: errBoomWrite}
335		failures, err := NormalizeReader(strings.NewReader(input), w)
336		if !errors.Is(err, errBoomWrite) {
337			t.Fatalf("write failure while flushing the final batch must reach the caller, got %v", err)
338		}
339		if failures != 0 {
340			t.Fatalf("all-legal input plus write fault must report 0 failures, got %d", failures)
341		}
342	}
343	
344	// TestNormalizeWriteFailureAtFinalFlushAfterInvalidLine is the same final-flush
345	// failure with an invalid line already accumulated: the count must survive.
346	func TestNormalizeWriteFailureAtFinalFlushAfterInvalidLine(t *testing.T) {
347		input := "not json\n" + validLog("ok") + "\n"
348		w := &failingWriter{failAfter: 0, fault: errBoomWrite}
349		failures, err := NormalizeReader(strings.NewReader(input), w)
350		if !errors.Is(err, errBoomWrite) {
351			t.Fatalf("write failure at final flush must reach the caller, got %v", err)
352		}
353		if failures != 1 {
354			t.Fatalf("the invalid line must still count as 1 after the write fault, got %d", failures)
355		}
356	}
357	
358	// TestNormalizeWriteFailureLeavesNoFabricatedFailureRecord checks the partial
359	// residue after a mid-stream write fault: it may contain truncated JSON, but
360	// every complete result line still parses to a real normalization result and
361	// there is no extra failure attributable to the output fault.
362	func TestNormalizeWriteFailureLeavesNoFabricatedFailureRecord(t *testing.T) {
363		var sb strings.Builder
364		sb.WriteString("first bad\n")
365		for i := 0; i < 60; i++ {
366			sb.WriteString(validLog(fmt.Sprintf("action-%02d", i)))
367			sb.WriteByte('\n')
368		}
369		w := &partialWriter{failAfter: 2, fault: errBoomWrite}
370		failures, err := NormalizeReader(strings.NewReader(sb.String()), w)
371		if !errors.Is(err, errBoomWrite) {
372			t.Fatalf("caller must receive the write error, got %v", err)
373		}
374		if failures != 1 {
375			t.Fatalf("only the one invalid log counts; the write fault adds none, got %d", failures)
376		}
377		results := decodeResultsLenient(t, w.varb.Bytes())
378		for i, r := range results {
379			line, _ := r["line"].(float64)
380			if line < 1 {
381				t.Fatalf("result %d has no real line number: %#v", i, r)
382			}
383			if r["ok"] == false {
384				// The only line-level failure permitted is the first input line.
385				if line != 1 {
386					t.Fatalf("write fault must not synthesize a line failure; failure found on line %v: %#v", line, r)
387				}
388			}
389		}
390	}
391	
392	// partialWriter accepts failAfter full Writes, then performs a partial write
393	// on the next call and reports the fault; afterwards every Write fails. It
394	// models a device that accepts some bytes of a batch and then breaks, which
395	// leaves genuinely partial JSON in the output.
396	type partialWriter struct {
397		varb      bytes.Buffer
398		failAfter int
399		fault     error
400		write     int
401	}
402	
403	func (w *partialWriter) Write(p []byte) (int, error) {
404		if w.write < w.failAfter {
405			w.write++
406			return w.varb.Write(p)
407		}
408		if w.write == w.failAfter {
409			w.write++
410			k := len(p) / 2
411			if k == 0 {
412				k = 1
413			}
414			w.varb.Write(p[:k])
415			return k, w.fault
416		}
417		return 0, w.fault
418	}
419	
420	// TestNormalizeReadErrorWinsOverCloseTimeWriteError: when reading has already
421	// failed and the final flush of successfully produced results also fails, the
422	// caller still receives the original read error — the later write fault must
423	// not mask the root cause.
424	func TestNormalizeReadErrorWinsOverCloseTimeWriteError(t *testing.T) {
425		r := &repeatReader{
426			chunks: []string{
427				validLog("a") + "\n",
428				validLog("b") + "\n",
429			},
430			fault:      errBoomRead,
431			faultAfter: -1,
432		}
433		w := &failingWriter{failAfter: 0, fault: errBoomWrite}
434		failures, err := NormalizeReader(r, w)
435		if !errors.Is(err, errBoomRead) {
436			t.Fatalf("earlier read error must be returned even when the final flush also fails, got %v", err)
437		}
438		if errors.Is(err, errBoomWrite) {
439			t.Fatalf("write error must not replace the read error, got %v", err)
440		}
441		if failures != 0 {
442			t.Fatalf("neither fault counts as a failed log, got %d", failures)
443		}
444	}
445	
446	// TestNormalizeReadErrorWinsOverMidStreamWriteError covers the same precedence
447	// when the writer breaks while results from already-read lines are being
448	// emitted, before the read fault is observed.
449	func TestNormalizeReadErrorWinsOverMidStreamWriteError(t *testing.T) {
450		// All lines arrive in the first chunk; the first underlying flush of
451		// those results fails before the next Read returns the fault.
452		r := &failingReader{
453			prefix:    strings.Repeat(validLog("x")+"\n", 200),
454			readFault: errBoomRead,
455		}
456		w := &failingWriter{failAfter: 1, fault: errBoomWrite}
457		failures, err := NormalizeReader(r, w)
458		if !errors.Is(err, errBoomRead) {
459			t.Fatalf("read error must remain the reported cause, got %v", err)
460		}
461		if failures != 0 {
462			t.Fatalf("faults must not be counted as failed logs, got %d", failures)
463		}
464	}
465	
466	// TestNormalizeCleanEOFWithoutNewline is the non-fault path that must stay
467	// distinct: a complete final log with no trailing newline is processed and
468	// written normally, with nil error.
469	func TestNormalizeCleanEOFWithoutNewline(t *testing.T) {
470		input := validLog("last")
471		var out bytes.Buffer
472		failures, err := NormalizeReader(strings.NewReader(input), &out)
473		if err != nil {
474			t.Fatalf("clean EOF must not be reported as an interruption, got %v", err)
475		}
476		if failures != 0 {
477			t.Fatalf("legal final line must not count as failure, got %d", failures)
478		}
479		results := assertResultsComplete(t, out.Bytes(), 1)
480		if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "last" {
481			t.Fatalf("unterminated final line must be processed normally: %#v", results[0])
482		}
483	}
484	
485	// TestNormalizeCleanEOFMixedLinesWithoutNewline: the unterminated last line is
486	// an invalid log; it is still a numbered per-line failure and the run error
487	// stays nil — validation failure is never confused with an I/O fault.
488	func TestNormalizeCleanEOFMixedLinesWithoutNewline(t *testing.T) {
489		input := validLog("a") + "\n" + "bad without newline"
490		var out bytes.Buffer
491		failures, err := NormalizeReader(strings.NewReader(input), &out)
492		if err != nil {
493			t.Fatalf("invalid final line at clean EOF is a validation failure, not I/O error: %v", err)
494		}
495		if failures != 1 {
496			t.Fatalf("expected 1 validation failure, got %d", failures)
497		}
498		results := assertResultsComplete(t, out.Bytes(), 2)
499		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
500			t.Fatalf("line 1: %#v", results[0])
501		}
502		if results[1]["line"] != float64(2) || results[1]["ok"] != true {
503			t.Fatalf("unterminated invalid line 2 must be a numbered failure: %#v", results[1])
504		}
505	}
506	
507	// TestNormalizeErrorsStayIdentifiable guarantees read faults, write faults,
508	// and per-line validation errors are not collapsed into one unclassifiable
509	// failure message.
510	func TestNormalizeErrorsStayIdentifiable(t *testing.T) {
511		// Read fault: returned directly.
512		r := &failingReader{prefix: validLog("a") + "\n", readFault: errBoomRead}
513		if _, err := NormalizeReader(r, io.Discard); !errors.Is(err, errBoomRead) {
514			t.Fatalf("read fault must stay identifiable via errors.Is, got %v", err)
515		}
516	
517		// Write fault: returned directly.
518		w := &failingWriter{failAfter: 0, fault: errBoomWrite}
519		if _, err := NormalizeReader(strings.NewReader(validLog("a")+"\n"), w); !errors.Is(err, errBoomWrite) {
520			t.Fatalf("write fault must stay identifiable via errors.Is, got %v", err)
521		}
522	
523		// Per-line validation error: nil run error, identifiable field message
524		// inside the result record.
525		var out bytes.Buffer
526		failures, err := NormalizeReader(strings.NewReader(`{"timestamp":"bad","action":"a"}`+"\n"), &out)
527		if err != nil || failures != 1 {
528			t.Fatalf("validation failure must keep run error nil, got failures=%d err=%v", failures, err)
529		}
530		results := assertResultsComplete(t, out.Bytes(), 1)
531		msg, _ := results[0]["error"].(string)
532		if !strings.Contains(msg, FieldTimestamp) {
533			t.Fatalf("line error must remain recognizable as %q, got %q", FieldTimestamp, msg)
534		}
535	}
536	
537	// TestNormalizeEmptyReadErrorIsNotEOF guards the distinction between a stream
538	// that fails immediately (before any bytes) and an empty stream at clean EOF.
539	func TestNormalizeEmptyReadErrorIsNotEOF(t *testing.T) {
540		r := &failingReader{prefix: "", readFault: errBoomRead}
541		var out bytes.Buffer
542		failures, err := NormalizeReader(r, &out)
543		if !errors.Is(err, errBoomRead) {
544			t.Fatalf("immediate read fault must be reported, got %v", err)
545		}
546		if failures != 0 || out.Len() != 0 {
547			t.Fatalf("fault before any data must produce no results and no failures, got failures=%d out=%q", failures, out.String())
548		}
549	}
